  "check_code": """"Deterministic post-state checks for the policy acknowledgement task."""

import json
import re
import sqlite3
from collections import Counter
from pathlib import Path


IDEMPOTENCY_KEY = "PSU-F25-CLEARANCE-20250919-POLICY-ACK"
SNAPSHOT_DATE = "2025-09-19"
RULE_CODES = (
    "DEG-TOTAL-180",
    "DEG-UPPER-62",
    "RES-FINAL75-45",
    "RES-PSU-150",
    "RES-LAST45-AF-25",
    "US-MIN-GRADE-DMINUS",
    "US-PNP-OFFERED-ONLY",
)
SUPPLEMENTAL_RULE_CODES = (
    "RES-ALTERNATIVE-OR",
    "RES-AF-DIFFERENTIATED",
    "US-CLUSTER-PNP-P",
)
PROTECTED_TABLES = (
    "policy_documents",
    "policy_rules",
    "policy_rule_crosswalk",
)


def _paths(workspace):
    environment_root = Path(workspace).resolve().parent
    repository_dir = environment_root / "system" / "psu_catalog_policy_repository"
    return repository_dir / "state.db", repository_dir / "state.db.pinned_backup"


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _target_acknowledgement(connection):
    return connection.execute(
        "SELECT * FROM policy_acknowledgements WHERE idempotency_key = ?",
        (IDEMPOTENCY_KEY,),
    ).fetchall()


def check_acknowledgement_metadata(workspace):
    database, _ = _paths(workspace)
    try:
        with _connect(database) as connection:
            rows = _target_acknowledgement(connection)
            total = connection.execute("SELECT COUNT(*) FROM policy_acknowledgements").fetchone()[0]
    except (sqlite3.Error, OSError) as exc:
        return {"score": 0, "detail": f"Could not read acknowledgement state: {exc}"}
    if len(rows) != 1 or total != 1:
        return {"score": 0, "detail": f"Expected exactly one acknowledgement and one target key row; found total={total}, target={len(rows)}."}
    row = rows[0]
    expected = {
        "clearance_cycle_id": "PSU-F25-CLEARANCE",
        "analyst_id": "Dana McAllister",
        "snapshot_date": SNAPSHOT_DATE,
        "idempotency_key": IDEMPOTENCY_KEY,
    }
    mismatches = []
    for field, value in expected.items():
        if _norm(row[field]) != _norm(value):
            mismatches.append(f"{field}={row[field]!r}")
    if not str(row["acknowledged_at"] or "").strip():
        mismatches.append("acknowledged_at is blank")
    if mismatches:
        return {"score": 0, "detail": "Acknowledgement metadata mismatch: " + "; ".join(mismatches)}
    return {"score": 1, "detail": f"One idempotent acknowledgement exists for {row['clearance_cycle_id']} under {row['analyst_id']}."}


def check_acknowledgement_note(workspace):
    database, _ = _paths(workspace)
    try:
        with _connect(database) as connection:
            rows = _target_acknowledgement(connection)
    except (sqlite3.Error, OSError) as exc:
        return {"score": 0, "detail": f"Could not read acknowledgement note: {exc}"}
    if len(rows) != 1:
        return {"score": 0, "detail": "The target acknowledgement is missing or duplicated."}
    note = _norm(rows[0]["acknowledgement_note"])
    date_ok = "2025 09 19" in note or "september 19 2025" in note
    family_checks = {
        "credit": "credit" in note and ("180" in note or "62" in note or "minimum" in note),
        "residency": "residenc" in note,
        "differentiated-grade": "differentiated" in note or "a f" in note or "af" in note.split(),
        "University Studies minimum-grade": "university studies" in note and ("minimum grade" in note or "d minus" in note or "dmin" in note),
        "cluster Pass/No Pass": "cluster" in note and ("pass no pass" in note or "p np" in note or "pnp" in note),
    }
    missing = [name for name, present in family_checks.items() if not present]
    if not date_ok:
        missing.insert(0, "September 19, 2025 snapshot")
    if missing:
        return {"score": 0, "detail": "Acknowledgement note is missing: " + ", ".join(missing)}
    return {"score": 1, "detail": "The note identifies the snapshot and all required control families."}


def _resolve_expected_items(connection):
    expected = {}
    for code in RULE_CODES + SUPPLEMENTAL_RULE_CODES:
        rules = connection.execute(
            """
            SELECT r.rule_id, r.document_id, d.controlled_version
            FROM policy_rules r
            JOIN policy_documents d ON d.document_id = r.document_id
            WHERE r.rule_code = ?
              AND r.effective_date <= ?
              AND (r.retired_date IS NULL OR r.retired_date >= ?)
              AND d.effective_date <= ?
              AND (d.retired_date IS NULL OR d.retired_date >= ?)
              AND d.document_status = 'active'
            """,
            (code, SNAPSHOT_DATE, SNAPSHOT_DATE, SNAPSHOT_DATE, SNAPSHOT_DATE),
        ).fetchall()
        if len(rules) != 1:
            raise ValueError(f"{code} resolved to {len(rules)} effective rules")
        rule = rules[0]
        crosswalks = connection.execute(
            """
            SELECT crosswalk_id
            FROM policy_rule_crosswalk
            WHERE rule_id = ?
              AND effective_date <= ?
              AND (retired_date IS NULL OR retired_date >= ?)
            ORDER BY crosswalk_id
            """,
            (rule["rule_id"], SNAPSHOT_DATE, SNAPSHOT_DATE),
        ).fetchall()
        if not crosswalks:
            raise ValueError(f"{code} has no effective crosswalk")
        expected[code] = {
            "document_id": rule["document_id"],
            "controlled_version": rule["controlled_version"],
            "crosswalk_ids": [row["crosswalk_id"] for row in crosswalks],
        }
    return expected


def check_acknowledgement_items(workspace):
    database, _ = _paths(workspace)
    try:
        with _connect(database) as connection:
            acknowledgements = _target_acknowledgement(connection)
            if len(acknowledgements) != 1:
                return {"score": 0, "detail": "The target acknowledgement is missing or duplicated."}
            expected = _resolve_expected_items(connection)
            rows = connection.execute(
                "SELECT * FROM policy_acknowledgement_items WHERE acknowledgement_id = ? ORDER BY rule_code",
                (acknowledgements[0]["acknowledgement_id"],),
            ).fetchall()
            total_items = connection.execute("SELECT COUNT(*) FROM policy_acknowledgement_items").fetchone()[0]
    except (sqlite3.Error, OSError, ValueError) as exc:
        return {"score": 0, "detail": f"Could not validate acknowledgement items: {exc}"}
    if total_items != len(rows):
        return {"score": 0, "detail": f"Acknowledgement item table has target={len(rows)} but total={total_items}; duplicate or orphaned items found."}
    actual = {}
    for row in rows:
        code = row["rule_code"]
        if code in actual:
            return {"score": 0, "detail": f"Duplicate acknowledgement item for {code}."}
        if code not in expected:
            return {"score": 0, "detail": f"Rule {code} is outside the required or explicitly supporting acknowledgement set."}
        try:
            crosswalk_ids = json.loads(row["crosswalk_ids_json"])
        except (TypeError, json.JSONDecodeError):
            return {"score": 0, "detail": f"Invalid crosswalk JSON for {code}."}
        actual[code] = {
            "document_id": row["document_id"],
            "controlled_version": row["controlled_version"],
            "crosswalk_ids": sorted(crosswalk_ids),
        }
    missing = [code for code in RULE_CODES if code not in actual]
    if missing:
        return {"score": 0, "detail": "Required acknowledgement rules are missing: " + ", ".join(missing)}
    mismatches = [code for code, item in actual.items() if item != expected[code]]
    if mismatches:
        return {"score": 0, "detail": "Persisted item tuples do not match independently resolved effective rules for: " + ", ".join(sorted(mismatches))}
    return {"score": 1, "detail": "All required rule items and any explicitly supporting supplemental items match effective document versions and crosswalks."}


def _table_rows(connection, table, apply_known_corrections=False):
    columns = [row[1] for row in connection.execute(f"PRAGMA table_info({table})")]
    rows = connection.execute(f"SELECT * FROM {table}").fetchall()
    normalized = []
    for row in rows:
        values = {column: row[column] for column in columns}
        if apply_known_corrections and table == "policy_rules" and values.get("rule_id") == "PR-011":
            values["minimum_value"] = 1.7
            values["unit"] = "grade_points"
        normalized.append(tuple(values[column] for column in columns))
    return Counter(normalized)


def check_preexisting_policy_integrity(workspace):
    database, baseline = _paths(workspace)
    try:
        with _connect(database) as current, _connect(baseline) as pinned:
            changed = [
                table
                for table in PROTECTED_TABLES
                if _table_rows(current, table)
                != _table_rows(pinned, table, apply_known_corrections=True)
            ]
    except (sqlite3.Error, OSError) as exc:
        return {"score": 0, "detail": f"Could not compare protected policy data: {exc}"}
    if changed:
        return {"score": 0, "detail": "Pre-existing policy data changed in: " + ", ".join(changed)}
    return {"score": 1, "detail": "All pre-existing policy documents, rules, and crosswalks remain unchanged."}
